import {ordinaryV10Fixture} from './v10OrdinaryApply.testFixture'
import {metadataRow} from './metadataPrefix.testFixture'
import {BrowserHistoricalMetadataDependency} from './historicalMetadataDependency'
import {scope} from './bootstrap.testFixture'
import type {BrowserSyncTransaction} from './syncDurability'

/** Every positive outcome is generated by actual accepted F/H/O/Metadata owners. */
export async function historicalMetadataFixture(strategy:Parameters<typeof ordinaryV10Fixture>[0]='keep_both',protocol:2|3=3,compressed=false,options:{pending?:boolean;fork?:boolean;stage?:boolean}={}){
 const f=await ordinaryV10Fixture(strategy,protocol,compressed,options.stage)
 const ordinary=await f.receive('historical-independent',null,1,false,{protocol:3,compressed:true});await f.owner.apply(scope,ordinary.sequence)
 const original=await f.receive('content-note',f.children[0]!.event_id,5,strategy==='delete',{protocol:3,compressed:false});await f.h.apply(scope,original.sequence)
 let retained:typeof original|undefined
 if(strategy==='keep_both'){retained=await f.receive('retained-note',f.children[1]!.event_id,5,false,{protocol:3,compressed:true});await f.h.apply(scope,retained.sequence)}
 const update=await metadataRow(f.f,(f.f.db.cursors[0] as {pull_cursor:number}).pull_cursor+1,{revision:2,parent:f.m.event.header.event_id,compressed:true})
 await f.f.metadata.apply(scope,update.reference,f.f.auth,f.f.bindings as never,f.f.keys as never)
 const pending=options.pending?await f.receive('pending'):undefined
 if(options.fork){const fork=await f.receive('content-note',f.children[0]!.event_id,5,strategy==='delete',{protocol:3});await f.h.apply(scope,fork.sequence)}
 const deletion=await metadataRow(f.f,(f.f.db.cursors[0] as {pull_cursor:number}).pull_cursor+1,{revision:3,parent:update.event.header.event_id,change:e=>{e.header.operation='delete';e.metadata=null;e.deleted_at=e.header.updated_at}})
 await f.f.metadata.apply(scope,deletion.reference,f.f.auth,f.f.bindings as never,f.f.keys as never)
 let active=true
 const create=(transaction:BrowserSyncTransaction=f.transaction)=>new BrowserHistoricalMetadataDependency(transaction,()=>active).bind(f.f.auth,f.f.bindings as never,f.f.keys as never,f.device)
 return{...f,ordinary,original,retained,update,deletion,pending,create,reader:create(),revokeReader:()=>{active=false}}
}
